<script setup>
import { ref } from "vue";
import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";

// Categorías
const categorias = ["Comida Rápida", "Bebidas", "Postres", "Platos Fuertes"];
const categoriaSeleccionada = ref("Comida Rápida");

// Estado
const mostrarAlerta = ref(false);
const pedido = ref([]);
const mostrarCarrito = ref(false);

// 30 PLATOS MANUALES
const platos = ref([
  { id: 1, nombre: "Hamburguesa Clásica", categoria: "Comida Rápida", precio: 15000, stock: 10, descripcion: "Carne a la parrilla", ingredientes: "Carne, pan, lechuga", imagen: "data:image/jpeg;base64," },
  { id: 2, nombre: "Pizza Pepperoni", categoria: "Comida Rápida", precio: 20000, stock: 10, descripcion: "Pizza italiana", ingredientes: "Queso, pepperoni", imagen: "data:image/jpeg;base64," },
  { id: 3, nombre: "Perro Caliente", categoria: "Comida Rápida", precio: 12000, stock: 10, descripcion: "Hot dog clásico", ingredientes: "Salchicha, pan", imagen: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSqTuJJ0FVjCuI3Pflt8McDEpLHn89PjIUftQ&s" },
  { id: 4, nombre: "Papas Fritas", categoria: "Comida Rápida", precio: 8000, stock: 10, descripcion: "Papas crujientes", ingredientes: "Papas, sal", imagen: "data:image/jpeg;base64," },
  { id: 5, nombre: "Sandwich", categoria: "Comida Rápida", precio: 10000, stock: 10, descripcion: "Sandwich mixto", ingredientes: "Jamón, queso", imagen: "data:image/jpeg;base64," },
  { id: 6, nombre: "Tacos", categoria: "Comida Rápida", precio: 14000, stock: 10, descripcion: "Tacos mexicanos", ingredientes: "Carne, tortilla", imagen: "data:image/jpeg;base64," },
  { id: 7, nombre: "Arepa con Queso", categoria: "Comida Rápida", stock: 10, precio: 9000, descripcion: "Arepa tradicional", ingredientes: "Maíz, queso", imagen: "data:image/jpeg;base64," },
  { id: 8, nombre: "Nuggets", categoria: "Comida Rápida", precio: 13000, stock: 10, descripcion: "Pollo crujiente", ingredientes: "Pollo empanizado", imagen: "data:image/jpeg;base64," },

  { id: 9, nombre: "Jugo Natural", categoria: "Bebidas", precio: 8000, stock: 10, descripcion: "Jugo de frutas", ingredientes: "Frutas frescas", imagen: "data:image/jpeg;base64," },
  { id: 10, nombre: "Malteada", categoria: "Bebidas", precio: 12000, stock: 10, descripcion: "Malteada cremosa", ingredientes: "Leche, helado", imagen: "data:image/jpeg;base64," },
  { id: 11, nombre: "Café", categoria: "Bebidas", precio: 5000, stock: 10, descripcion: "Café caliente", ingredientes: "Café", imagen: "data:image/jpeg;base64," },
  { id: 12, nombre: "Chocolate Caliente", categoria: "Bebidas", stock: 10, precio: 7000, descripcion: "Chocolate caliente", ingredientes: "Chocolate, leche", imagen: "data:image/jpeg;base64," },
  { id: 13, nombre: "Gaseosa", categoria: "Bebidas", precio: 4000, stock: 10, descripcion: "Refresco", ingredientes: "Gas", imagen: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTf9YJxyALjINMbrCovxNmtWlBIlnGg5_Z4KA&s" },
  { id: 14, nombre: "Agua", categoria: "Bebidas", precio: 3000, stock: 10, descripcion: "Agua natural", ingredientes: "Agua", imagen: "data:image/jpeg;base64," },
  { id: 15, nombre: "Limonada", categoria: "Bebidas", precio: 6000, stock: 10, descripcion: "Limonada fresca", ingredientes: "Limón", imagen: "data:image/jpeg;base64," },

  { id: 16, nombre: "Pastel de Chocolate", categoria: "Postres", stock: 10, precio: 10000, descripcion: "Pastel dulce", ingredientes: "Chocolate", imagen: "data:image/jpeg;base64," },
  { id: 17, nombre: "Helado", categoria: "Postres", precio: 7000, stock: 10, descripcion: "Helado frío", ingredientes: "Leche", imagen: "data:image/jpeg;base64," },
  { id: 18, nombre: "Brownie", categoria: "Postres", precio: 8000, stock: 10, descripcion: "Brownie", ingredientes: "Chocolate", imagen: "data:image/jpeg;base64," },
  { id: 19, nombre: "Cheesecake", categoria: "Postres", precio: 11000, stock: 10, descripcion: "Torta de queso", ingredientes: "Queso crema", imagen: "data:image/jpeg;base64," },
  { id: 20, nombre: "Donas", categoria: "Postres", precio: 6000, stock: 10, descripcion: "Donas dulces", ingredientes: "Harina", imagen: "data:image/jpeg;base64," },
  { id: 21, nombre: "Flan", categoria: "Postres", precio: 7000, stock: 10, descripcion: "Postre cremoso", ingredientes: "Leche", imagen: "data:image/jpeg;base64," },
  { id: 22, nombre: "Gelatina", categoria: "Postres", precio: 5000, stock: 10, descripcion: "Postre ligero", ingredientes: "Gelatina", imagen: "data:image/jpeg;base64," },

  { id: 23, nombre: "Arroz con Pollo", categoria: "Platos Fuertes", stock: 10, precio: 18000, descripcion: "Plato tradicional", ingredientes: "Arroz, pollo", imagen: "data:image/jpeg;base64," },
  { id: 24, nombre: "Carne Asada", categoria: "Platos Fuertes", precio: 25000, stock: 10, descripcion: "Carne a la parrilla", imagen: "data:image/jpeg;base64," },
  { id: 25, nombre: "Pollo a la Plancha", categoria: "Platos Fuertes", precio: 20000, stock: 10, descripcion: "Pollo saludable", imagen: "data:image/jpeg;base64," },
  { id: 26, nombre: "Pescado Frito", categoria: "Platos Fuertes", precio: 22000, stock: 10, descripcion: "Pescado crujiente", imagen: "data:image/jpeg;base64," },
  { id: 27, nombre: "Spaghetti", categoria: "Platos Fuertes", precio: 17000, stock: 10, descripcion: "Pasta italiana", imagen: "data:image/jpeg;base64," },
  { id: 28, nombre: "Lasaña", categoria: "Platos Fuertes", precio: 19000, stock: 10, descripcion: "Lasaña casera", imagen: "data:image/jpeg;base64," },
  { id: 29, nombre: "Sopa de Pollo", categoria: "Platos Fuertes", precio: 15000, stock: 10, descripcion: "Sopa caliente", imagen: "data:image/jpeg;base64," },
  { id: 30, nombre: "Bandeja Paisa", categoria: "Platos Fuertes", precio: 30000, stock: 10, descripcion: "Plato típico", imagen: "data:image/jpeg;base64," }
]);


function platosFiltrados() {
  return platos.value.filter(p => p.categoria === categoriaSeleccionada.value);
}


function agregar(plato) {
  if (plato.stock <= 0) {
    alert("No quedan más productos disponibles");
    return;
  }
  let existe = pedido.value.find(p => p.id === plato.id);
  if (existe) existe.cantidad++;
  else pedido.value.push({ ...plato, cantidad: 1 });

  plato.stock--;
}

function eliminar(i) {

  let producto = pedido.value[i];

  let platoOriginal = platos.value.find(p => p.id === producto.id);

  if (platoOriginal) {
    platoOriginal.stock += producto.cantidad;
  }

  pedido.value.splice(i, 1);
}
function actualizarCantidad(event, producto) {

  let nuevaCantidad = parseInt(event.target.value) || 1;

  let platoOriginal = platos.value.find(p => p.id === producto.id);

  // diferencia entre cantidad anterior y nueva
  let diferencia = nuevaCantidad - producto.cantidad;

  // si quiere aumentar más de lo disponible
  if (diferencia > platoOriginal.stock) {

    alert("No hay suficiente stock disponible");

    event.target.value = producto.cantidad;

    return;
  }

  // actualizar stock
  platoOriginal.stock -= diferencia;

  // actualizar cantidad
  producto.cantidad = nuevaCantidad;
}

function total() {
  return pedido.value.reduce((sum, p) => sum + p.precio * (parseInt(p.cantidad) || 0), 0);
}

// PDF
function generarFactura() {

  if (pedido.value.length === 0) {
    mostrarAlerta.value = true;
    setTimeout(() => mostrarAlerta.value = false, 3000);
    return;
  }

  const doc = new jsPDF();

  // COLORES
  const rojo = [255, 59, 59];
  const naranja = [255, 122, 24];
  const oscuro = [20, 23, 29];

  // FONDO HEADER
  doc.setFillColor(...oscuro);
  doc.rect(0, 0, 210, 40, "F");

  // TÍTULO
  doc.setFont("helvetica", "bold");
  doc.setFontSize(24);

  doc.setTextColor(...rojo);
  doc.text(" BRASA VIVA", 14, 20);

  doc.setFontSize(11);
  doc.setTextColor(255,255,255);

  doc.text("Factura de compra", 14, 30);

  // FECHA
  const fecha = new Date().toLocaleString();

  doc.setFontSize(10);
  doc.setTextColor(120);

  doc.text("Fecha: " + fecha, 14, 50);

  // TABLA
  const rows = pedido.value.map(p => [
    p.nombre,
    p.cantidad,
    "$" + p.precio,
    "$" + (p.precio * p.cantidad)
  ]);

  autoTable(doc, {
    startY: 60,

    head: [["Producto", "Cant.", "Precio", "Subtotal"]],

    body: rows,

    theme: "grid",

    headStyles: {
      fillColor: rojo,
      textColor: 255,
      fontStyle: "bold",
      halign: "center"
    },

    bodyStyles: {
      fillColor: [245,245,245],
      textColor: 30
    },

    alternateRowStyles: {
      fillColor: [230,230,230]
    },

    styles: {
      fontSize: 11,
      cellPadding: 4,
      halign: "center",
      valign: "middle"
    }
  });

  // TOTAL
  const finalY = doc.lastAutoTable.finalY + 15;

  doc.setFillColor(...naranja);

  doc.roundedRect(120, finalY - 8, 70, 15, 3, 3, "F");

  doc.setFontSize(16);
  doc.setTextColor(255,255,255);

  doc.text("TOTAL: $" + total(), 128, finalY + 2);

  // MENSAJE FINAL
  doc.setFontSize(11);

  doc.setTextColor(100);

  doc.text(
    "Gracias por tu compra :)",
    14,
    finalY + 25
  );

  // GUARDAR PDF
  doc.save("Factura_Brasa_Viva.pdf");

  // LIMPIAR PEDIDO
  pedido.value = [];
}
</script>

<template>
  <div>
    <h1>🔥BRASA VIVA</h1>

    <div class="categorias">
      <button v-for="cat in categorias" :key="cat" @click="categoriaSeleccionada = cat"
        :class="{ activa: categoriaSeleccionada === cat }">
        {{ cat }}
      </button>
    </div>

    <!-- 🔥 ARREGLO AQUÍ -->
    <div class="platos">
      <div v-for="plato in platosFiltrados()" :key="plato.id" class="card">
        <img :src="plato.imagen" />
        <h3>{{ plato.nombre }}</h3>
        <p>{{ plato.descripcion }}</p>
        <small>{{ plato.ingredientes }}</small>
        <p class="precio">${{ plato.precio }}</p>
        <div class="stock-control">

          <p class="stock">
            Disponibles: {{ plato.stock }}
          </p>

          <button class="stock-btn" @click="plato.stock++">+</button>
        </div>
        <button @click="agregar(plato)" :disabled="plato.stock <= 0">{{ plato.stock <= 0 ? "Agotado" : "Agregar"
        }}</button>
      </div>
    </div>

   <!-- BOTON CARRITO -->
<div class="carrito-btn" @click="mostrarCarrito = !mostrarCarrito">
  🛒
  <span class="contador">
    {{ pedido.length }}
  </span>
</div>

<!-- PANEL DEL CARRITO -->
<div class="carrito-panel" v-if="mostrarCarrito">

  <h2>🔥 Tu Pedido</h2>

  <p v-if="pedido.length === 0">
    No hay productos
  </p>

  <div v-if="pedido.length > 0">

    <div v-for="(p, i) in pedido" :key="i" class="item">

      <div class="info">
        <h4>{{ p.nombre }}</h4>
        <p>${{ p.precio * p.cantidad }}</p>
      </div>

      <input
        type="number"
        :value="p.cantidad"
        min="1"
        @input="actualizarCantidad($event, p)"
      />

      <button @click="eliminar(i)">
        ❌
      </button>

    </div>

    <h3 class="total">
      Total: ${{ total() }}
    </h3>

    <button class="finalizar" @click="generarFactura">
      Finalizar compra
    </button>

  </div>
</div>

    <div v-if="mostrarAlerta" class="alerta">
      ⚠️ No hay productos en el pedido
    </div>
  </div>
</template>

<style>
